import React, { useMemo, useState } from "react";

import {
  Background,
  Controls,
  Handle,
  MiniMap,
  Position,
  ReactFlow,
} from "reactflow";

import "reactflow/dist/style.css";

import {
  workers,
  partitions,
  topologyStatus,
} from "../data/mockData";


/* ============================================================
   CUSTOM NODES
   ============================================================ */

function KafkaNode() {
  return (
    <div className="detailed-topology-node">

      <Handle
        type="source"
        position={Position.Right}
      />

      <div className="detailed-node-header">
        <strong>Kafka</strong>

        <span className="topology-health-dot">
          ●
        </span>
      </div>

      <div className="detailed-node-main-value">
        {partitions.length}
      </div>

      <div className="detailed-node-label">
        partitions
      </div>

      <div className="detailed-node-info">
        truck-telemetry
      </div>

    </div>
  );
}


function ProcessorNode() {

  const healthyWorkers =
    workers.filter(
      (worker) => worker.status === "healthy"
    ).length;

  return (
    <div className="detailed-topology-node processor-node">

      <div className="detailed-node-header">

        <strong>
          Stream Processor
        </strong>

