   ============================================================ */

const nodeTypes = {
  kafka: KafkaNode,
  processor: ProcessorNode,
  aggregation: AggregationNode,
  rocksdb: RocksDBNode,
  prometheus: PrometheusNode,
  ui: UINode,
};


/* ============================================================
   TOPOLOGY PAGE
   ============================================================ */

export default function Topology() {

  const [showMinimap, setShowMinimap] =
    useState(true);


  /* ==========================================================
     DERIVED DATA
     ========================================================== */

  const healthyWorkers = useMemo(
    () =>
      workers.filter(
        (worker) =>
          worker.status === "healthy"
      ).length,
    []
  );


  const failedWorkers = useMemo(
    () =>
      workers.filter(
        (worker) =>
          worker.status === "failed"
      ).length,
    []
  );


  const activePartitions = useMemo(
    () =>
      partitions.filter(
        (partition) =>
          partition.status === "active"
      ).length,
    []
  );


  /* ==========================================================
     NODES
     ========================================================== */

  const nodes = useMemo(
    () => [

      {
        id: "kafka",
        type: "kafka",

        position: {
          x: 50,
          y: 180,
        },
      },

      {
        id: "processor",
        type: "processor",

        position: {
          x: 330,
          y: 180,
        },
      },

      {
        id: "aggregation",
        type: "aggregation",

        position: {
          x: 630,
          y: 180,
        },
      },

      {
        id: "rocksdb",
        type: "rocksdb",

        position: {
          x: 630,
          y: 350,
        },
      },

      {
        id: "prometheus",
        type: "prometheus",

        position: {
          x: 930,
          y: 350,
        },
      },

      {
        id: "ui",
        type: "ui",

        position: {
          x: 1230,
          y: 350,
        },
      },

    ],
    []
  );


  /* ==========================================================
     EDGES
     ========================================================== */

  const edges = useMemo(
    () => [

      {
        id: "kafka-processor",

        source: "kafka",
        target: "processor",

        animated: true,
      },

      {
        id: "processor-aggregation",

        source: "processor",
        target: "aggregation",

        animated: true,
      },

      {
        id: "processor-rocksdb",

        source: "processor",
        target: "rocksdb",

        style: {
          strokeDasharray: "6 4",
        },
      },

      {
        id: "processor-prometheus",

        source: "processor",
        target: "prometheus",

        style: {
          strokeDasharray: "6 4",
        },
      },

      {
        id: "prometheus-ui",

        source: "prometheus",
        target: "ui",

        style: {
          strokeDasharray: "6 4",
        },
      },

    ],
    []
  );


  /* ==========================================================
     RENDER
     ========================================================== */

  return (

    <div className="topology-page">


      {/* =====================================================
          HEADER
      ====================================================== */}

      <div className="topology-page-header">

        <div>

          <h1>
            Topology
          </h1>

          <p>
            Detailed StreamForge processing architecture.
          </p>

        </div>

      </div>


      {/* =====================================================
          SUMMARY
      ====================================================== */}

      <div className="topology-summary">


        <div className="topology-summary-item">

          <span>
            Workers
          </span>

          <strong>
            {healthyWorkers}/{workers.length}
          </strong>

          <small>
            healthy
          </small>

        </div>


        <div className="topology-summary-item">

          <span>
            Partitions
          </span>

          <strong>
            {activePartitions}/{partitions.length}
          </strong>

          <small>
            active
          </small>

        </div>


        <div className="topology-summary-item">

          <span>
            Processor
          </span>

          <strong>
            {topologyStatus.processor.status}
          </strong>

          <small>
            Bytewax / Faust
          </small>

        </div>


        <div className="topology-summary-item">

          <span>
            Worker Failures
          </span>

          <strong
            className={
              failedWorkers > 0
                ? "failure-value"
                : ""
            }
          >
            {failedWorkers}
          </strong>

          <small>
            detected
          </small>

        </div>

      </div>


      {/* =====================================================
          TOOLBAR
      ====================================================== */}

      <div className="topology-toolbar">

        <div>

          <strong>
            Stream Processing Pipeline
          </strong>

          <span>
            Data flow and monitoring architecture
          </span>

        </div>


        <div className="topology-toolbar-actions">

          <button
            className="topology-toolbar-button"
            onClick={() =>
              setShowMinimap(
                (value) => !value
              )
            }
          >

            {showMinimap
              ? "Hide Minimap"
              : "Show Minimap"}

          </button>

        </div>

      </div>


      {/* =====================================================
          REACT FLOW
      ====================================================== */}

      <div className="detailed-topology-container">

        <ReactFlow
          nodes={nodes}
          edges={edges}
          nodeTypes={nodeTypes}
          fitView
          nodesConnectable={false}
          nodesDraggable={true}
          elementsSelectable={true}
        >

          <Background />

          <Controls />

          {showMinimap && (
            <MiniMap />
          )}

        </ReactFlow>

      </div>


      {/* =====================================================
          LEGEND
      ====================================================== */}

      <div className="topology-legend">

        <span className="legend-title">
          Legend
        </span>


        <div className="legend-item">

          <span className="legend-line" />

          <span>
            Data Flow
          </span>

        </div>


        <div className="legend-item">

          <span className="legend-dashed-line" />

          <span>
            Monitoring / State
          </span>

        </div>

      </div>


    </div>
  );
}
